import { LoggerService } from '@backstage/backend-plugin-api';
import { ActionsRegistryService } from '@backstage/backend-plugin-api/alpha';
import { SearchEngine } from '@backstage/plugin-search-backend-node';
import { SearchIndexService } from '@backstage/plugin-search-backend-node/alpha';

/**
 * Determines whether a document location uses a safe (http/https) protocol.
 *
 * Relative URLs (which have no explicit protocol) are considered safe, while
 * absolute URLs using protocols such as `javascript:` or `data:` are not.
 */
const hasSafeLocation = (location: string): boolean => {
  let url: URL;
  try {
    url = new URL(location);
  } catch {
    // Not an absolute URL (e.g. a relative location), so there is no unsafe
    // protocol to worry about.
    return true;
  }

  return url.protocol === 'http:' || url.protocol === 'https:';
};

/**
 * Registers a search query action with the provided actions registry, allowing
 * agents to query the search engine.
 */
export const createQueryAction = ({
  engine,
  actionsRegistry,
  searchIndexService,
  logger,
}: {
  engine: SearchEngine;
  actionsRegistry: ActionsRegistryService;
  searchIndexService: SearchIndexService;
  logger: LoggerService;
}): void => {
  const documentTypes = Object.keys(searchIndexService.getDocumentTypes());

  actionsRegistry.register({
    name: 'search',
    title: 'Search',
    attributes: {
      destructive: false,
      readOnly: true,
      idempotent: true,
    },
    description: [
      'Query the Backstage search engine and return matching documents.',
      documentTypes.length
        ? `Available document types: ${documentTypes.join(', ')}.`
        : undefined,
    ]
      .filter(Boolean)
      .join(' '),
    schema: {
      input: z =>
        z.object({
          term: z
            .string()
            .describe('The term to search for across the search index'),
          types: z
            .array(z.string())
            .optional()
            .describe(
              'The document types to restrict the search to. Omit to search all types.',
            ),
          filters: z
            .record(z.any())
            .optional()
            .describe('A nested object of filters to apply to the query'),
          pageLimit: z
            .number()
            .optional()
            .describe('The maximum number of results to return per page'),
          pageCursor: z
            .string()
            .optional()
            .describe('The cursor for the page of results to return'),
        }),
      output: z =>
        z.object({
          results: z
            .array(
              z.object({
                type: z
                  .string()
                  .describe('The type of the matching document'),
                document: z
                  .object({
                    title: z.string().describe('The title of the document'),
                    text: z.string().describe('The text of the document'),
                    location: z
                      .string()
                      .describe('The location (URL) of the document'),
                  })
                  .passthrough()
                  .describe('The matching document'),
              }),
            )
            .describe('The list of matching search results'),
          nextPageCursor: z
            .string()
            .optional()
            .describe('The cursor for the next page of results, if any'),
          totalItems: z
            .number()
            .optional()
            .describe('The total number of results matching the query'),
          hasMoreResults: z
            .boolean()
            .describe('Whether there are more results to fetch'),
        }),
    },
    action: async ({ input }) => {
      const resultSet = await engine.query({
        term: input.term,
        types: input.types,
        filters: input.filters,
        pageLimit: input.pageLimit,
        pageCursor: input.pageCursor,
      });

      const results = resultSet.results
        .filter(result => {
          if (hasSafeLocation(result.document.location)) {
            return true;
          }

          logger.info(
            `Excluding search result with unsafe location protocol: ${result.document.location}`,
          );
          return false;
        })
        .map(result => {
          const { authorization, ...document } = result.document;
          return {
            type: result.type,
            document,
          };
        });

      return {
        output: {
          results,
          nextPageCursor: resultSet.nextPageCursor,
          totalItems: resultSet.numberOfResults,
          hasMoreResults: Boolean(resultSet.nextPageCursor),
        },
      };
    },
  });
};
